+            console.warn("github_webhook_job_retrying", {
+              attempts: message.attempts,
+              error: errorName(error),
+              messageId: message.id,
+              queue: batch.queue,
+              status: errorStatus(error),
+            });
+            message.retry({ delaySeconds: retryDelaySeconds });
